#!/usr/bin/env python3
"""Reproducible OULAD benchmark for CogniSync (M1-M5).

Predicts the score of each OULAD assessment attempt from that student's earlier
attempts only.  Baselines are historical mean and last score; trainable models
are Ridge, Random Forest and XGBoost.

Protocol
--------
* Rows: scored, non-banked assessment attempts with >= 1 visible prior attempt.
* Features: generated by ``pipeline.build_features`` at
  ``prediction_time = deadline - horizon`` (default 7 days) using strictly
  earlier submissions of *other* assessments only.  No ``final_result``, no
  mood/stress.  ``--with-vle`` adds daily-click engagement features, so the
  score-only vs score + engagement comparison is two runs of this script.
* Split: chronological presentation cohorts
  (train 2013B+2013J, val 2014B, test 2014J) with pairwise disjoint students.
* Hyper-parameters: selected on validation MAE, then refit on train+val.
  Test is touched once.
* Metrics: MAE, RMSE, R^2, bias, with student-clustered bootstrap 95% CIs.

Usage
-----
    python score_model/src/oulad_benchmark.py
    python score_model/src/oulad_benchmark.py --out-json score_model/docs/benchmarks/oulad_results.json \
        --report score_model/docs/benchmarks/M5_OULAD_report.md
    python score_model/src/oulad_benchmark.py --with-vle --out-json score_model/docs/benchmarks/oulad_results_vle.json \
        --report score_model/docs/benchmarks/M5_OULAD_report_vle.md
"""

from __future__ import annotations

import argparse
import json
import sys
import time
from pathlib import Path

import numpy as np
import pandas as pd
from sklearn.compose import ColumnTransformer
from sklearn.ensemble import RandomForestRegressor
from sklearn.impute import SimpleImputer
from sklearn.linear_model import Ridge
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder, StandardScaler
from xgboost import XGBRegressor

sys.path.insert(0, str(Path(__file__).resolve().parent))
import pipeline as pit  # noqa: E402

SEED = 42
N_BOOTSTRAP = 1000
RIDGE_ALPHAS = (0.03, 0.1, 0.3, 1.0, 3.0, 10.0, 30.0, 100.0)
RF_LEAVES = (1, 3, 5, 10, 20)
XGB_DEPTHS = (3, 4, 6, 8)
XGB_JOBS = 4  # 16-core box: n_jobs=-1 is ~19x slower for hist on this machine

MODEL_ORDER = ["Historical mean", "Last score", "Ridge", "Random Forest", "XGBoost"]
INTERVAL_LEVEL = 0.80  # target share of test scores inside the range
MIN_GROUP_ROWS = 200  # assessment types with fewer validation rows use the pooled width


def conformal_halfwidths(abs_resid: np.ndarray, groups: np.ndarray, level: float = INTERVAL_LEVEL) -> dict:
    """Split-conformal half-width per group, from held-out absolute residuals."""

    def q(r: np.ndarray) -> float:
        n = len(r)
        return float(np.quantile(r, min(1.0, np.ceil((n + 1) * level) / n), method="higher"))

    widths = {"__all__": q(abs_resid)}
    for g in np.unique(groups):
        r = abs_resid[groups == g]
        if len(r) >= MIN_GROUP_ROWS:
            widths[str(g)] = q(r)
    return widths


def apply_intervals(pred: np.ndarray, groups: np.ndarray, widths: dict) -> tuple[np.ndarray, np.ndarray]:
    h = np.array([widths.get(str(g), widths["__all__"]) for g in groups])
    return np.clip(pred - h, 0.0, 100.0), np.clip(pred + h, 0.0, 100.0)


# --------------------------------------------------------------------------- #
# Metrics
# --------------------------------------------------------------------------- #


def regression_metrics(y: np.ndarray, pred: np.ndarray) -> dict:
    err = pred - y
    ss_res = float(np.sum(err**2))
    ss_tot = float(np.sum((y - y.mean()) ** 2))
    return {
        "n": int(len(y)),
        "mae": float(np.mean(np.abs(err))),
        "rmse": float(np.sqrt(np.mean(err**2))),
        "r2": float(1.0 - ss_res / ss_tot) if ss_tot > 0 else float("nan"),
        "bias": float(np.mean(err)),
        "abs_err_p90": float(np.percentile(np.abs(err), 90)),
    }


def clustered_bootstrap_ci(
    df: pd.DataFrame, y: np.ndarray, pred: np.ndarray, n_boot: int = N_BOOTSTRAP, seed: int = SEED
) -> dict:
    """Percentile 95% CI for MAE/RMSE, resampling students (not rows)."""
    frame = pd.DataFrame(
        {
            "id_student": df["id_student"].to_numpy(),
            "ae": np.abs(pred - y),
            "se": (pred - y) ** 2,
        }
    )
    per_student = frame.groupby("id_student", sort=True).agg(
        n=("ae", "size"), sae=("ae", "sum"), sse=("se", "sum")
    )
    n = per_student["n"].to_numpy(dtype=float)
    sae = per_student["sae"].to_numpy(dtype=float)
    sse = per_student["sse"].to_numpy(dtype=float)
    rng = np.random.default_rng(seed)
    idx = rng.integers(0, len(n), size=(n_boot, len(n)))
    maes = sae[idx].sum(axis=1) / n[idx].sum(axis=1)
    rmses = np.sqrt(sse[idx].sum(axis=1) / n[idx].sum(axis=1))
    return {
        "mae_ci95": [float(np.percentile(maes, 2.5)), float(np.percentile(maes, 97.5))],
        "rmse_ci95": [float(np.percentile(rmses, 2.5)), float(np.percentile(rmses, 97.5))],
        "n_boot": int(n_boot),
        "clusters": int(len(n)),
    }


def error_distribution(y: np.ndarray, pred: np.ndarray) -> dict:
    err = pred - y
    return {
        "mean": float(err.mean()),
        "std": float(err.std(ddof=0)),
        "p05": float(np.percentile(err, 5)),
        "p25": float(np.percentile(err, 25)),
        "p50": float(np.percentile(err, 50)),
        "p75": float(np.percentile(err, 75)),
        "p95": float(np.percentile(err, 95)),
        "share_abs_gt_10": float(np.mean(np.abs(err) > 10)),
        "share_abs_gt_20": float(np.mean(np.abs(err) > 20)),
    }


# --------------------------------------------------------------------------- #
# Models
# --------------------------------------------------------------------------- #


def preprocessor(scale_numeric: bool) -> ColumnTransformer:
    numeric_steps = [("impute", SimpleImputer(strategy="median"))]
    if scale_numeric:
        numeric_steps.append(("scale", StandardScaler()))
    categorical = Pipeline(
        [
            ("impute", SimpleImputer(strategy="most_frequent")),
            ("onehot", OneHotEncoder(handle_unknown="ignore", sparse_output=False, min_frequency=10)),
        ]
    )
    return ColumnTransformer(
        [
            ("num", Pipeline(numeric_steps), pit.NUMERIC_FEATURES),
            ("cat", categorical, pit.CATEGORICAL_FEATURES),
        ]
    )


def fit_ridge(train: pd.DataFrame, val: pd.DataFrame) -> tuple[Pipeline, dict, pd.DataFrame]:
    ytr = train["score"].to_numpy(dtype=float)
    yva = val["score"].to_numpy(dtype=float)
    rows = []
    best = None
    for alpha in RIDGE_ALPHAS:
        model = Pipeline(
            [("pre", preprocessor(scale_numeric=True)), ("model", Ridge(alpha=alpha))]
        )
        model.fit(train[pit.FEATURE_COLUMNS], ytr)
        pred = model.predict(val[pit.FEATURE_COLUMNS])
        metrics = regression_metrics(yva, pred)
        rows.append({"candidate": f"alpha={alpha:g}", **metrics})
        if best is None or metrics["mae"] < best[0]:
            best = (metrics["mae"], model, {"alpha": alpha}, pred)
    return best[1], {**best[2], "val_mae": best[0]}, pd.DataFrame(rows), best[3]


def fit_random_forest(train: pd.DataFrame, val: pd.DataFrame) -> tuple[Pipeline, dict, pd.DataFrame]:
    ytr = train["score"].to_numpy(dtype=float)
    yva = val["score"].to_numpy(dtype=float)
    rows = []
    best = None
    for leaf in RF_LEAVES:
        model = Pipeline(
            [
                ("pre", preprocessor(scale_numeric=False)),
                (
                    "model",
                    RandomForestRegressor(
                        n_estimators=300,
                        min_samples_leaf=leaf,
                        max_features=0.5,
                        n_jobs=-1,
                        random_state=SEED,
                    ),
                ),
            ]
        )
        model.fit(train[pit.FEATURE_COLUMNS], ytr)
        pred = model.predict(val[pit.FEATURE_COLUMNS])
        metrics = regression_metrics(yva, pred)
        rows.append({"candidate": f"min_samples_leaf={leaf}", **metrics})
        if best is None or metrics["mae"] < best[0]:
            best = (metrics["mae"], model, {"min_samples_leaf": leaf, "n_estimators": 300}, pred)
    return best[1], {**best[2], "val_mae": best[0]}, pd.DataFrame(rows), best[3]


def fit_xgboost(train: pd.DataFrame, val: pd.DataFrame) -> tuple[Pipeline, dict, pd.DataFrame]:
    ytr = train["score"].to_numpy(dtype=float)
    yva = val["score"].to_numpy(dtype=float)
    pre = preprocessor(scale_numeric=False)
    xtr = pre.fit_transform(train[pit.FEATURE_COLUMNS])
    xva = pre.transform(val[pit.FEATURE_COLUMNS])

    rows = []
    best = None
    for depth in XGB_DEPTHS:
        model = XGBRegressor(
            n_estimators=1200,
            learning_rate=0.08,
            max_depth=depth,
            subsample=0.9,
            colsample_bytree=0.8,
            min_child_weight=5,
            reg_lambda=1.0,
            tree_method="hist",
            n_jobs=XGB_JOBS,
            random_state=SEED,
            early_stopping_rounds=60,
            eval_metric="mae",
        )
        model.fit(xtr, ytr, eval_set=[(xva, yva)], verbose=False)
        pred = model.predict(xva)
        metrics = regression_metrics(yva, pred)
        rows.append({"candidate": f"max_depth={depth}", "best_iteration": int(model.best_iteration), **metrics})
        if best is None or metrics["mae"] < best[0]:
            best = (metrics["mae"], model, {"max_depth": depth, "best_iteration": int(model.best_iteration)}, pred)
    return best[1], {**best[2], "val_mae": best[0]}, pd.DataFrame(rows), best[3]


def refit_and_predict(name: str, best_fit, train, val, test) -> np.ndarray:
    """Refit the selected configuration on train+val, predict test."""
    train_val = pd.concat([train, val], axis=0, ignore_index=True)
    y = train_val["score"].to_numpy(dtype=float)
    x = train_val[pit.FEATURE_COLUMNS]
    x_test = test[pit.FEATURE_COLUMNS]

    if name == "Ridge":
        _, params = best_fit
        # Fresh pipeline with the selected alpha.
        final = Pipeline(
            [
                ("pre", preprocessor(scale_numeric=True)),
                ("model", Ridge(alpha=params["alpha"])),
            ]
        )
        final.fit(x, y)
        return final.predict(x_test)

    if name == "Random Forest":
        _, params = best_fit
        final = Pipeline(
            [
                ("pre", preprocessor(scale_numeric=False)),
                (
                    "model",
                    RandomForestRegressor(
                        n_estimators=params["n_estimators"],
                        min_samples_leaf=params["min_samples_leaf"],
                        max_features=0.5,
                        n_jobs=-1,
                        random_state=SEED,
                    ),
                ),
            ]
        )
        final.fit(x, y)
        return final.predict(x_test)

    if name == "XGBoost":
        _, params = best_fit
        pre = preprocessor(scale_numeric=False)
        xtr = pre.fit_transform(x)
        xte = pre.transform(x_test)
        n_rounds = max(int(params["best_iteration"]) + 1, 50)
        final = XGBRegressor(
            n_estimators=n_rounds,
            learning_rate=0.08,
            max_depth=params["max_depth"],
            subsample=0.9,
            colsample_bytree=0.8,
            min_child_weight=5,
            reg_lambda=1.0,
            tree_method="hist",
            n_jobs=XGB_JOBS,
            random_state=SEED,
        )
        final.fit(xtr, y, verbose=False)
        return final.predict(xte)

    raise ValueError(name)


# --------------------------------------------------------------------------- #
# Reporting helpers
# --------------------------------------------------------------------------- #


def section(title: str) -> None:
    print(f"\n{'=' * 78}\n{title}\n{'=' * 78}")


def fmt_ci(value: float, ci: list[float]) -> str:
    return f"{value:6.3f} [{ci[0]:6.3f}, {ci[1]:6.3f}]"


def ascii_error_chart(rows: list[dict], metric: str, label: str, width: int = 58) -> list[str]:
    ck = f"{metric}_ci95"
    vmax = max(r[ck][1] for r in rows) * 1.04
    lines = [
        f"ASCII {label} (95% CI whisker '-', point '#'; 1 char = {vmax / width:.3f} marks)",
    ]
    for r in sorted(rows, key=lambda z: z[metric]):
        lo, hi = r[ck]
        p = int(round(r[metric] / vmax * width))
        a = int(round(lo / vmax * width))
        b = int(round(hi / vmax * width))
        line = ["."] * (width + 1)
        for i in range(a, b + 1):
            line[i] = "-"
        line[p] = "#"
        lines.append(
            f"  {r['model']:<17} {r[metric]:6.3f} [{lo:6.3f}, {hi:6.3f}] |{''.join(line)}|"
        )
    return lines


def markdown_table(df: pd.DataFrame) -> str:
    cols = list(df.columns)
    out = ["| " + " | ".join(cols) + " |", "|" + "|".join(["---"] * len(cols)) + "|"]
    for _, row in df.iterrows():
        vals = []
        for c in cols:
            v = row[c]
            if isinstance(v, float):
                vals.append(f"{v:.4f}")
            else:
                vals.append(str(v))
        out.append("| " + " | ".join(vals) + " |")
    return "\n".join(out)


def json_safe(obj):
    if isinstance(obj, dict):
        return {str(k): json_safe(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [json_safe(v) for v in obj]
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (np.floating,)):
        return float(obj)
    if isinstance(obj, np.ndarray):
        return [json_safe(v) for v in obj.tolist()]
    if isinstance(obj, pd.DataFrame):
        return json_safe(obj.to_dict(orient="records"))
    return obj


# --------------------------------------------------------------------------- #
# Main
# --------------------------------------------------------------------------- #


def main() -> int:
    global SEED

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data-dir", default=None, help="OULAD directory (default: repo raw data path)")
    parser.add_argument("--seed", type=int, default=SEED)
    parser.add_argument("--bootstrap", type=int, default=N_BOOTSTRAP)
    parser.add_argument("--out-json", default=None, help="write machine-readable results here")
    parser.add_argument("--report", default=None, help="write markdown report here")
    parser.add_argument("--skip-leakage", action="store_true", help="skip the (slow) leakage suite")
    parser.add_argument("--horizon-days", type=float, default=pit.PREDICTION_HORIZON_DAYS,
                        help="predict this many days before each deadline")
    parser.add_argument("--with-vle", action="store_true",
                        help="add studentVle click features (score + engagement model)")
    parser.add_argument("--out-preds", default=None,
                        help="write per-row test predictions and ranges here (.csv or .csv.gz)")
    args = parser.parse_args()

    SEED = args.seed
    pit.PREDICTION_HORIZON_DAYS = args.horizon_days
    if args.with_vle:
        pit.enable_vle_features()
    feature_set = "score history + metadata + VLE engagement" if args.with_vle else "score history + metadata"
    t_start = time.time()

    section("1. DATA")
    tables = pit.load_oulad(args.data_dir, with_vle=args.with_vle)
    raw_rows = int(len(tables["studentAssessment"]))
    print(f"Loaded: assessments={len(tables['assessments'])}, courses={len(tables['courses'])}, "
          f"studentAssessment={raw_rows}, studentInfo={len(tables['studentInfo'])}, "
          f"studentRegistration={len(tables['studentRegistration'])}")
    print(f"Feature set: {feature_set}; prediction {args.horizon_days:g} days before each deadline.")
    print("Excluded by design: vle.csv metadata, final_result, mood/stress/fatigue labels.")

    features = pit.build_features(tables)
    print(f"Scored, non-banked attempts: {len(features)} of {raw_rows} "
          f"({100 * len(features) / raw_rows:.1f}%); target mean={features['score'].mean():.2f}, "
          f"sd={features['score'].std(ddof=0):.2f}")

    section("2. SPLIT (chronological presentation cohorts, disjoint students)")
    split = pit.chronological_student_split(features)
    print(split["audit"].to_string(index=False))
    print(f"Student overlap: {split['student_overlap']}")
    print(f"Rows dropped to keep students disjoint: {split['dropped']}")
    train, val, test = split["splits"]["train"], split["splits"]["val"], split["splits"]["test"]
    print(f"Test presentations: {sorted(test['code_presentation'].unique())}; "
          f"test target mean={test['score'].mean():.2f}")

    leakage = None
    if not args.skip_leakage:
        section("3. LEAKAGE TESTS")
        leakage = pit.run_leakage_suite(tables, features, split)
        a = leakage["audit"]
        print(f"[A] Point-in-time audit: rows={a['rows']}, history ordering violations={a['history_violations']}, "
              f"target score in features={a['target_score_in_features']}, final_result in frame={a['final_result_in_frame']}, "
              f"infinite values={a['infinite_values']}, imputed NaN cells={a['nan_cells_imputed']} -> "
              f"{'PASS' if a['passed'] else 'FAIL'}")
        s = leakage["spot_check"]
        print(f"[B] Independent spot recomputation: rows={s['rows_checked']}, "
              f"max|d prior_n|={s['max_prior_n_diff']}, max|d prior_mean|={s['max_prior_mean_diff']:.2e}, "
              f"max|d prior_last|={s['max_prior_last_diff']:.2e} -> {'PASS' if s['passed'] else 'FAIL'}")
        f = leakage["future_invariance"]
        print(f"[C] Future-row invariance: kept first {f['keep_fraction']:.0%} of each student's attempts, "
              f"compared {f['rows_compared']} rows; max numeric diff={f['max_numeric_abs_diff']:.2e}, "
              f"categoricals identical={f['categoricals_identical']} -> {'PASS' if f['passed'] else 'FAIL'}")
        print(f"[D] Student-disjoint splits: {leakage['student_overlap']} -> "
              f"{'PASS' if all(v == 0 for v in leakage['student_overlap'].values()) else 'FAIL'}")
        print("[E] Deliberately leaky negative controls (should be caught):")
        for name, probe in leakage["probes"].items():
            print(f"      {name:<22} MAE={probe['mae']:8.4f}  RMSE={probe['rmse']:8.4f}  "
                  f"R2={probe['r2']:7.4f}  flagged={probe['flagged']}")
        print(f"LEAKAGE SUITE: {'PASS' if leakage['passed'] else 'FAIL'}")

    section("4. BASELINES (test)")
    y_test = test["score"].to_numpy(dtype=float)
    predictions: dict[str, np.ndarray] = {
        "Historical mean": test["prior_mean"].to_numpy(dtype=float),
        "Last score": test["prior_last"].to_numpy(dtype=float),
    }
    assert np.isfinite(predictions["Historical mean"]).all()
    assert np.isfinite(predictions["Last score"]).all()
    y_val = val["score"].to_numpy(dtype=float)
    for name, col in [("Historical mean", "prior_mean"), ("Last score", "prior_last")]:
        val_m = regression_metrics(y_val, val[col].to_numpy(dtype=float))
        test_m = regression_metrics(y_test, predictions[name])
        print(f"{name:<17} val MAE={val_m['mae']:.3f} RMSE={val_m['rmse']:.3f} R2={val_m['r2']:.4f} | "
              f"test MAE={test_m['mae']:.3f} RMSE={test_m['rmse']:.3f} R2={test_m['r2']:.4f}")

    section("5. MODEL SELECTION (validation MAE; test untouched until step 6)")
    selection_frames = {}

    print("\nRidge")
    ridge_fit = fit_ridge(train, val)
    selection_frames["Ridge"] = ridge_fit[2]
    print(ridge_fit[2][["candidate", "mae", "rmse", "r2"]].to_string(index=False))

    print("\nRandom Forest")
    rf_fit = fit_random_forest(train, val)
    selection_frames["Random Forest"] = rf_fit[2]
    print(rf_fit[2][["candidate", "mae", "rmse", "r2"]].to_string(index=False))

    print("\nXGBoost (early stopping on validation)")
    xgb_fit = fit_xgboost(train, val)
    selection_frames["XGBoost"] = xgb_fit[2]
    print(xgb_fit[2][["candidate", "best_iteration", "mae", "rmse", "r2"]].to_string(index=False))

    section("6. TEST RESULTS")
    t0 = time.time()
    predictions["Ridge"] = refit_and_predict("Ridge", ridge_fit[:2], train, val, test)
    predictions["Random Forest"] = refit_and_predict("Random Forest", rf_fit[:2], train, val, test)
    predictions["XGBoost"] = refit_and_predict("XGBoost", xgb_fit[:2], train, val, test)
    print(f"Refits on train+val and test prediction took {time.time() - t0:.1f}s")

    per_model = {}
    for name in MODEL_ORDER:
        pred = predictions[name]
        per_model[name] = {
            "test": regression_metrics(y_test, pred),
            "error_distribution": error_distribution(y_test, pred),
            "bootstrap": clustered_bootstrap_ci(test, y_test, pred, n_boot=args.bootstrap, seed=args.seed),
        }

    last_mae = per_model["Last score"]["test"]["mae"]
    print(f"\n{'Model':<20} {'MAE [95% CI]':<28} {'RMSE [95% CI]':<28} {'R2':>7} {'dMAE vs last':>14}")
    print("-" * 102)
    for name in MODEL_ORDER:
        m = per_model[name]["test"]
        b = per_model[name]["bootstrap"]
        delta = 100.0 * (last_mae - m["mae"]) / last_mae
        print(
            f"{name:<20} {fmt_ci(m['mae'], b['mae_ci95']):<28} "
            f"{fmt_ci(m['rmse'], b['rmse_ci95']):<28} {m['r2']:7.4f} {delta:>13.2f}%"
        )

    section(f"6b. {INTERVAL_LEVEL:.0%} PREDICTION RANGES (split conformal per assessment type)")
    # Widths come from validation residuals of the train-only fit; test rows never set them.
    val_preds = {
        "Historical mean": val["prior_mean"].to_numpy(dtype=float),
        "Last score": val["prior_last"].to_numpy(dtype=float),
        "Ridge": ridge_fit[3],
        "Random Forest": rf_fit[3],
        "XGBoost": xgb_fit[3],
    }
    val_groups = val["assessment_type"].to_numpy()
    test_groups = test["assessment_type"].to_numpy()
    interval_rows = []
    intervals = {}
    for name in MODEL_ORDER:
        assert np.isfinite(val_preds[name]).all(), name
        widths = conformal_halfwidths(np.abs(val_preds[name] - y_val), val_groups)
        lo, hi = apply_intervals(predictions[name], test_groups, widths)
        intervals[name] = (lo, hi)
        inside = (y_test >= lo) & (y_test <= hi)
        for atype in ["All", *sorted(np.unique(test_groups))]:
            mask = np.ones(len(y_test), bool) if atype == "All" else test_groups == atype
            interval_rows.append({
                "model": name, "assessment_type": atype, "n": int(mask.sum()),
                "half_width": widths.get(atype, widths["__all__"]) if atype != "All" else None,
                "coverage": float(inside[mask].mean()), "mean_width": float((hi - lo)[mask].mean()),
            })
    interval_df = pd.DataFrame(interval_rows)
    print(interval_df.to_string(index=False, float_format=lambda x: f"{x:.3f}"))

    if args.out_preds:
        cols = ["id_student", "id_assessment", "code_module", "code_presentation", "assessment_type", "score"]
        out = test[cols].reset_index(drop=True).copy()
        for name in MODEL_ORDER:
            key = name.lower().replace(" ", "_")
            out[f"{key}_pred"] = predictions[name]
            out[f"{key}_lo"], out[f"{key}_hi"] = intervals[name]
        path = Path(args.out_preds)
        path.parent.mkdir(parents=True, exist_ok=True)
        out.to_csv(path, index=False, float_format="%.3f")
        print(f"\nWrote per-row test predictions: {path} ({len(out):,} rows)")

    section("7. ERROR DISTRIBUTION BY ASSESSMENT TYPE (test)")
    type_rows = []
    for name in MODEL_ORDER:
        pred = predictions[name]
        for atype, g in test.groupby("assessment_type", sort=True):
            idx = g.index
            m = regression_metrics(g["score"].to_numpy(dtype=float), pred[test.index.get_indexer(idx)])
            d = error_distribution(g["score"].to_numpy(dtype=float), pred[test.index.get_indexer(idx)])
            type_rows.append(
                {
                    "model": name,
                    "assessment_type": atype,
                    "n": m["n"],
                    "MAE": m["mae"],
                    "RMSE": m["rmse"],
                    "R2": m["r2"],
                    "bias": d["mean"],
                    "err_sd": d["std"],
                    "err_p10": float(np.percentile(pred[test.index.get_indexer(idx)] - g["score"].to_numpy(dtype=float), 10)),
                    "err_p90": float(np.percentile(pred[test.index.get_indexer(idx)] - g["score"].to_numpy(dtype=float), 90)),
                    "p90_abs_err": m["abs_err_p90"],
                }
            )
    type_df = pd.DataFrame(type_rows)
    print(type_df.to_string(index=False, float_format=lambda x: f"{x:.3f}"))

    # Compact MAE matrix for readability.
    mae_matrix = type_df.pivot(index="assessment_type", columns="model", values="MAE")[MODEL_ORDER]
    print("\nMAE matrix (rows = assessment type, columns = model):")
    print(mae_matrix.to_string(float_format=lambda x: f"{x:.3f}"))

    section("8. ERROR BY COURSE MODULE (test; best model + baselines)")
    best_model = min(MODEL_ORDER, key=lambda n: per_model[n]["test"]["mae"])
    module_rows = []
    for name in ["Historical mean", "Last score", best_model]:
        pred = predictions[name]
        for module, g in test.groupby("code_module", sort=True):
            pos = test.index.get_indexer(g.index)
            m = regression_metrics(g["score"].to_numpy(dtype=float), pred[pos])
            module_rows.append(
                {"model": name, "code_module": module, "n": m["n"], "MAE": m["mae"], "RMSE": m["rmse"], "R2": m["r2"]}
            )
    module_df = pd.DataFrame(module_rows)
    print(module_df.to_string(index=False, float_format=lambda x: f"{x:.3f}"))
    print(f"\nBest test model: {best_model} (MAE {per_model[best_model]['test']['mae']:.3f})")

    section("9. ERROR-BAR CHART")
    chart_rows = [
        {
            "model": name,
            "mae": per_model[name]["test"]["mae"],
            "mae_ci95": per_model[name]["bootstrap"]["mae_ci95"],
            "rmse": per_model[name]["test"]["rmse"],
            "rmse_ci95": per_model[name]["bootstrap"]["rmse_ci95"],
        }
        for name in MODEL_ORDER
    ]
    print("\n".join(ascii_error_chart(chart_rows, "mae", "test MAE")))
    print()
    print("\n".join(ascii_error_chart(chart_rows, "rmse", "test RMSE")))

    chart_spec = (
        "Figure 1 - OULAD score-prediction error bars. Two horizontal panels sharing a y-axis "
        f"({', '.join(MODEL_ORDER)}), ordered by test MAE. Panel A: point = test MAE, whisker = "
        f"95% CI from {args.bootstrap} student-clustered bootstrap resamples; Panel B: same for RMSE. "
        f"n_test={len(test)} attempts from {test['id_student'].nunique()} students (2014J holdout, "
        "unseen students). A dashed vertical rule marks the last-score baseline MAE; labels show "
        "absolute MAE and delta vs last score. Error bars are student-clustered because attempts "
        "within a student are correlated. All models are on identical test rows. "
        "Figure 2 - error distribution by assessment type: grouped box/violin plots of signed "
        "residual (prediction - actual) for TMA/CMA/Exam, including the 5th/50th/95th percentiles, "
        "so systematic over/under-prediction by assessment format is visible. "
        "Figure 3 - per-module MAE heatmap (7 modules x 5 models). Colors use a sequential scale "
        "with per-cell n annotated; the 2014J presentation contains modules unseen in training "
        "(CCC), which is expected to raise error there."
    )
    print("\nCHART DESCRIPTION")
    print(textwrap_indent(chart_spec))

    def go_no_go() -> tuple[bool, str]:
        best = per_model[best_model]["test"]
        improvement = 100.0 * (last_mae - best["mae"]) / last_mae
        ok = best["mae"] < last_mae and improvement >= 3.0
        return ok, (
            f"Best model {best_model}: MAE {best['mae']:.3f} vs last-score {last_mae:.3f} "
            f"({improvement:+.2f}%). Gate (beat last score by >=3% MAE): {'GO' if ok else 'NO-GO'}."
        )

    gate_ok, gate_text = go_no_go()
    print("\nGO / NO-GO")
    print(gate_text)

    # ------------------------------------------------------------------ #
    # Persist
    # ------------------------------------------------------------------ #
    results = {
        "protocol": {
            "rows": "scored, non-banked attempts with >=1 prior attempt",
            "prediction_time": f"deadline - {args.horizon_days:g} days",
            "feature_set": feature_set,
            "features": list(pit.FEATURE_COLUMNS),
            "train_presentations": list(pit.TRAIN_PRESENTATIONS),
            "val_presentations": list(pit.VAL_PRESENTATIONS),
            "test_presentations": list(pit.TEST_PRESENTATIONS),
            "student_disjoint": split["student_overlap"],
            "seed": args.seed,
            "n_bootstrap": args.bootstrap,
            "excluded_inputs": ["vle.csv", "final_result", "mood", "stress", "fatigue"]
            + ([] if args.with_vle else ["studentVle.csv"]),
        },
        "data": {
            "raw_attempt_rows": raw_rows,
            "scored_non_banked_rows": len(features),
            "benchmark_rows": int(len(train) + len(val) + len(test)),
            "target_mean": float(features["score"].mean()),
            "target_sd": float(features["score"].std(ddof=0)),
        },
        "split_audit": split["audit"].to_dict(orient="records"),
        "dropped_for_disjointness": split["dropped"],
        "leakage": leakage,
        "model_selection": {k: v.to_dict(orient="records") for k, v in selection_frames.items()},
        "selected_params": {
            "Ridge": ridge_fit[1],
            "Random Forest": rf_fit[1],
            "XGBoost": xgb_fit[1],
        },
        "test_metrics": {k: v["test"] for k, v in per_model.items()},
        "test_bootstrap_ci": {k: v["bootstrap"] for k, v in per_model.items()},
        "test_error_distribution": {k: v["error_distribution"] for k, v in per_model.items()},
        "prediction_intervals": {
            "level": INTERVAL_LEVEL,
            "method": "split conformal (absolute residual), per assessment type, calibrated on validation",
            "rows": interval_df.to_dict(orient="records"),
        },
        "error_by_assessment_type": type_df.to_dict(orient="records"),
        "error_by_module": module_df.to_dict(orient="records"),
        "chart_description": chart_spec,
        "go_no_go": {"pass": bool(gate_ok), "text": gate_text, "best_model": best_model},
        "runtime_seconds": None,
    }
    results["runtime_seconds"] = round(time.time() - t_start, 1)

    if args.out_json:
        path = Path(args.out_json)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(json_safe(results), indent=2))
        print(f"\nWrote JSON results: {path}")

    if args.report:
        path = Path(args.report)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(render_report(results, per_model, type_df, module_df, chart_rows, args))
        print(f"Wrote markdown report: {path}")

    print(f"\nRuntime: {results['runtime_seconds']}s")
    return 0 if gate_ok else 0  # reporting success; gate is a research decision, not a crash


# --------------------------------------------------------------------------- #
# Markdown report
# --------------------------------------------------------------------------- #


def textwrap_indent(text: str, width: int = 92) -> str:
    import textwrap

    return "\n".join(textwrap.wrap(text, width=width))


def render_report(results, per_model, type_df, module_df, chart_rows, args) -> str:
    lines = [
        "# M5 - OULAD benchmark report",
        "",
        "Generated by `score_model/src/oulad_benchmark.py`. Benchmark only: OULAD scores are not "
        "CogniSync quiz scores and no transfer claim is made.",
        "",
        "## Protocol",
        "",
        f"- Rows: {results['data']['scored_non_banked_rows']:,} scored, non-banked attempts; "
        f"{results['data']['benchmark_rows']:,} benchmark rows after requiring >=1 prior attempt.",
        f"- Features ({results['protocol']['feature_set']}): point-in-time at "
        f"`{results['protocol']['prediction_time']}`; strictly earlier submissions of other "
        "assessments only (the target attempt is always excluded).",
        "- Split: chronological cohorts, pairwise disjoint students: "
        f"train {results['protocol']['train_presentations']}, val {results['protocol']['val_presentations']}, "
        f"test {results['protocol']['test_presentations']}.",
        f"- Seed {args.seed}; {args.bootstrap} student-clustered bootstrap draws.",
        "- Excluded: " + ", ".join(f"`{x}`" for x in results["protocol"]["excluded_inputs"]) + ".",
        "",
        "## Split audit",
        "",
        markdown_table(pd.DataFrame(results["split_audit"])),
        "",
        "## Leakage tests",
        "",
    ]
    if results.get("leakage"):
        lk = results["leakage"]
        lines += [
            f"- Point-in-time audit: {'PASS' if lk['audit']['passed'] else 'FAIL'} "
            f"({lk['audit']['history_violations']} ordering violations; "
            f"{lk['audit']['nan_cells_imputed']:,} imputed numeric cells).",
            f"- Independent spot recomputation: {'PASS' if lk['spot_check']['passed'] else 'FAIL'} "
            f"({lk['spot_check']['rows_checked']} rows, max diff "
            f"{lk['spot_check']['max_prior_mean_diff']:.2e}).",
            f"- Future-row invariance: {'PASS' if lk['future_invariance']['passed'] else 'FAIL'} "
            f"({lk['future_invariance']['rows_compared']:,} comparable rows, max numeric diff "
            f"{lk['future_invariance']['max_numeric_abs_diff']:.2e}).",
            f"- Student overlap: {lk['student_overlap']}.",
            "- Negative controls: target-score probe R2 "
            f"{lk['probes']['target_score_probe']['r2']:.4f} (flagged="
            f"{lk['probes']['target_score_probe']['flagged']}); future-mean probe R2 "
            f"{lk['probes']['future_mean_probe']['r2']:.4f} (flagged="
            f"{lk['probes']['future_mean_probe']['flagged']}).",
            f"- **Leakage suite: {'PASS' if lk['passed'] else 'FAIL'}**",
        ]
    else:
        lines.append("Leakage suite skipped at runtime (`--skip-leakage`).")
    lines += [
        "",
        "## Test results (2014J holdout, unseen students)",
        "",
        "| Model | MAE | MAE 95% CI | RMSE | RMSE 95% CI | R2 | Bias |",
        "|---|---:|---|---:|---|---:|---:|",
    ]
    for name in MODEL_ORDER:
        m = per_model[name]["test"]
        b = per_model[name]["bootstrap"]
        lines.append(
            f"| {name} | {m['mae']:.4f} | [{b['mae_ci95'][0]:.4f}, {b['mae_ci95'][1]:.4f}] | "
            f"{m['rmse']:.4f} | [{b['rmse_ci95'][0]:.4f}, {b['rmse_ci95'][1]:.4f}] | "
            f"{m['r2']:.4f} | {m['bias']:+.4f} |"
        )
    lines += [
        "",
        results["go_no_go"]["text"],
        "",
        f"## {results['prediction_intervals']['level']:.0%} prediction ranges",
        "",
        "Each prediction gets a range `[pred - w, pred + w]`, clipped to 0-100. The half-width `w` is the "
        "split-conformal quantile of absolute errors on the validation cohort (2014B), set separately "
        "for each assessment type. Coverage is the share of test scores that fall inside the range; "
        f"the target is {results['prediction_intervals']['level']:.0%}.",
        "",
        markdown_table(pd.DataFrame(results["prediction_intervals"]["rows"]).fillna("")),
        "",
        "## Error distribution by assessment type",
        "",
        markdown_table(
            type_df[
                ["model", "assessment_type", "n", "MAE", "RMSE", "R2", "bias", "err_sd", "err_p10", "err_p90", "p90_abs_err"]
            ]
        ),
        "",
        "## Error by module (test)",
        "",
        markdown_table(module_df),
        "",
        "## Error-bar chart",
        "",
        "```",
        *ascii_error_chart(chart_rows, "mae", "test MAE"),
        "```",
        "",
        results["chart_description"],
        "",
        "## Notes and caveats",
        "",
        "- This is an OULAD benchmark only. It is not evidence of transfer to CogniSync "
        "quiz scores, and no causal or grade-guarantee claim is made.",
        "- The 2014J test cohort is later than training and its assessment mix differs. "
        "BBB, for example, moves from many low-weight practice items in 2013 to four "
        "weighted TMAs in 2014. That distribution shift makes both history-only baselines "
        "have negative R2 on test even though their MAE is stable; the comparison is still "
        "on identical rows for every model.",
        "- Exam deadlines are missing for 11 OULAD assessments; their deadline is imputed "
        "as the module-presentation end (the median exam submission is 20 days before that).",
        "- The prediction instant is a fixed horizon before the deadline, so neither the "
        "target score nor the target's own submission timing is available to any feature.",
        "- A prior score is treated as known on its submission day. Real marking takes "
        "days, so the most recent visible score may not have been released yet; this "
        "slightly favours the history features.",
        "- Demographic fields are used only in this offline benchmark and must not be copied "
        "into CogniSync models without a separate fairness and product review.",
        "- Per-student clustered bootstrap CIs are used because a student's attempts are "
        "not independent observations.",
        "- Range widths are calibrated on validation errors of the train-only fit, while test "
        "predictions come from the train+val refit, so ranges are slightly conservative. "
        "Conformal coverage assumes validation and test errors look alike; 2014J is a later "
        "cohort, so the measured test coverage is the real check. Coverage holds on average "
        "over rows, not for each student.",
        "",
        "## Selected hyper-parameters",
        "",
        "```json",
        json.dumps(json_safe(results["selected_params"]), indent=2),
        "```",
        "",
        f"Runtime: {results['runtime_seconds']}s.",
        "",
    ]
    return "\n".join(lines)


if __name__ == "__main__":
    raise SystemExit(main())
